<?php

declare(strict_types=1);

namespace RtlyKit\Tests\Unit\Calendar;

use DateTimeZone;
use Illuminate\Database\Eloquent\Model;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use RtlyKit\Calendar\Hijri;
use RtlyKit\Laravel\Casts\JalaliCast;

/**
 * Values written by the real earlier releases (0.2.1 and 0.3.0), generated by installing
 * each tagged release from Packagist and committed in tests/Fixtures/compat/. The current
 * code must read them with the same meaning as the release that wrote them.
 *
 * What the old formats had already lost is stated here, not hidden: the 0.3.0 payload
 * writes the UTC offset in hours and minutes, so a moment in a zone with an offset that
 * has seconds (Asia/Tehran and Europe/Amsterdam before the 1920s) was already a few
 * seconds off in that payload. No reader can bring the missing seconds back.
 */
final class CompatibilityFixturesTest extends TestCase
{
    /** Cases whose zone had an offset with seconds when 0.3.0 wrote them. */
    private const LOST_OFFSET_SECONDS = ['tehran-1900', 'amsterdam-1900'];

    /** @return array<string, mixed> */
    private static function load(string $release): array
    {
        $data = json_decode((string) file_get_contents(__DIR__.'/../../Fixtures/compat/payloads-'.$release.'.json'), true, 512, JSON_THROW_ON_ERROR);
        self::assertSame($release, $data['release']);

        return $data;
    }

    /** @return iterable<string, array{string, array<string, mixed>}> */
    public static function payloads(): iterable
    {
        foreach (['0.2.1', '0.3.0'] as $release) {
            foreach (self::load($release)['payloads'] as $entry) {
                yield "{$release} {$entry['class']} {$entry['case']}" => [$release, $entry];
            }
        }
    }

    /** @param array<string, mixed> $entry */
    #[DataProvider('payloads')]
    public function test_payloads_of_earlier_releases_load_with_the_meaning_they_had(string $release, array $entry): void
    {
        $object = unserialize($entry['serialized']);

        self::assertInstanceOf($entry['class'], $object);
        self::assertSame($entry['restored_by_release']['U.u'], $object->format('U.u'), 'same moment as the release that wrote it restored');
        self::assertSame($entry['restored_by_release']['zone'], $object->getTimezone()->getName());
        if ($object instanceof Hijri && isset($entry['variant'])) {
            self::assertSame($entry['variant'], $object->getVariant()->value);
        }
    }

    /** @param array<string, mixed> $entry */
    #[DataProvider('payloads')]
    public function test_only_the_documented_information_was_already_lost(string $release, array $entry): void
    {
        $lost = (float) $entry['original']['U.u'] - (float) $entry['restored_by_release']['U.u'];

        if ($release === '0.3.0' && in_array($entry['case'], self::LOST_OFFSET_SECONDS, true)) {
            self::assertNotSame(0.0, $lost, 'the 0.3.0 payload rounds the offset to the minute');
            self::assertLessThan(60.0, abs($lost));

            return;
        }
        self::assertSame(0.0, $lost, "{$release} {$entry['class']} {$entry['case']}");
    }

    /** @param array<string, mixed> $entry */
    #[DataProvider('payloads')]
    public function test_a_value_read_from_an_old_payload_round_trips_through_the_current_format(string $release, array $entry): void
    {
        $object = unserialize($entry['serialized']);
        $copy = unserialize(serialize($object));

        self::assertSame($object->format('U.u'), $copy->format('U.u'));
        self::assertSame($object->getTimezone()->getName(), $copy->getTimezone()->getName());
        self::assertSame($object->__serialize()['offset'], $copy->__serialize()['offset']);
    }

    /** @return iterable<string, array{string, array<string, mixed>}> */
    public static function casts(): iterable
    {
        foreach (['0.2.1', '0.3.0'] as $release) {
            foreach (self::load($release)['casts'] as $i => $entry) {
                yield "{$release} #{$i} {$entry['default_zone']} {$entry['input']}" => [$release, $entry];
            }
        }
    }

    /** @param array<string, mixed> $entry */
    #[DataProvider('casts')]
    public function test_stored_cast_values_of_earlier_releases_read_the_same(string $release, array $entry): void
    {
        $previous = date_default_timezone_get();
        date_default_timezone_set($entry['default_zone']);
        try {
            $model = new class () extends Model {};
            foreach ([new JalaliCast(), new JalaliCast($entry['default_zone']), new JalaliCast('app')] as $cast) {
                $value = $cast->get($model, 'at', $entry['raw'], []);

                self::assertNotNull($value);
                self::assertSame($entry['instant_U'], $value->format('U'), $release);
                self::assertSame($entry['read_back_U'], $value->format('U'));
                // Saving the model again without touching the column keeps the stored text.
                self::assertSame($entry['raw'], $cast->set($model, 'at', $value, ['at' => $entry['raw']]));
            }
        } finally {
            date_default_timezone_set($previous);
        }
    }

    public function test_the_fixture_files_come_from_the_named_releases(): void
    {
        foreach (['0.2.1', '0.3.0'] as $release) {
            $data = self::load($release);
            self::assertNotEmpty($data['payloads']);
            self::assertNotEmpty($data['casts']);
            self::assertArrayNotHasKey('error', $data['payloads'][0]);
        }
        $legacy = self::load('0.2.1')['payloads'][0]['serialized'];
        self::assertStringContainsString("\0RtlyKit\\Calendar\\Jalali\0gregorian", $legacy, '0.2.1 wrote the property layout');
        $v1 = self::load('0.3.0')['payloads'][0]['serialized'];
        self::assertStringContainsString('s:7:"instant"', $v1);
        self::assertStringNotContainsString('offset', $v1, '0.3.0 payloads have no offset key');
        self::assertInstanceOf(DateTimeZone::class, (unserialize($v1))->getTimezone());
    }
}
